#include "stdlib/ml/base/loss/float32/squared_epsilon_insensitive_gradient.h"
#include <stdio.h>

int main( void ) {
	const float x[] = { -10.0f, -9.56f, -8.67f, -7.78f, -6.89f, 6.89f, 7.78f, 8.67f, 9.56f, 10.0f };
	const float e[] = { 0.0f, 1.0f, 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f };
	const float y[] = { -9.9f, -7.7f, -5.5f, -3.3f, -1.1f, 1.1f, 3.3f, 5.5f, 7.7f, 9.9f };
	const float p[] = { -5.0f, -3.89f, -2.78f, -1.67f, -0.56f, 0.56f, 1.67f, 2.78f, 3.89f, 5.0f };

	float v;
	int i;
	for ( i = 0; i < 10; i++ ) {
		v = stdlib_base_float32_squared_epsilon_insensitive_gradient( x[ i ], e[ i ], y[ i ], p[ i ] );
		printf( "squaredEpsilonInsensitiveGradient(%f, %f, %f, %f) = %f\n", x[ i ], e[ i ], y[ i ], p[ i ], v );
	}
}
